INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.111.0',
  '2026-10-01',
  'Тесты: проверка цветовосприятия с разбором по цветам',
  E'На странице «Тесты», рядом с колодами, появилась проверка цветовосприятия — те самые таблицы с числом из разноцветных кружков. Девять таблиц за прогон, числа каждый раз новые: приложение рисует таблицы само, запомнить их нельзя.\n\nГлавное — разбор. После каждого ответа таблицу можно перекрасить шестью способами: усилить разницу цветов, включить коррекцию (оттенок, который вы не различаете, переносится в различимые цвета), оставить одну светлоту, посмотреть, как эту же таблицу видит дальтоник, или просто подсветить ответ. Так видно не только «ошибся», но и какой именно оттенок не различился. Любую таблицу можно открыть заново из итогов.\n\nВ конце — счёт по типам: красно-зелёные таблицы отдельно (протан и дейтан), сине-жёлтые отдельно. Прохождения сохраняются, их видно списком при следующем заходе.\n\nПервая таблица контрольная: её видно при любом зрении. Если и она не узнана — дело в яркости экрана, ночном режиме или цветовом фильтре, и остальное считать нельзя. И главное: это скрининг, а не диагноз, по экрану цвета не проверяют.',
  E'Таблицы рисует клиент: оригинальные Ишихары — чужая интеллектуальная собственность, а фиксированный набор заучивается наизусть. Цвета строятся в LMS: пара «фон — фигура» отличается ровно тем каналом колбочек, который у этого типа не работает (протан L, дейтан M, тритан S), поэтому после проекции Вьено совпадает точно — замер даёт расстояние 0 между симуляциями при 80–165 для нормального зрения. Разница подбирается от большой к маленькой, пока оба цвета остаются в экранном диапазоне: обрезка ломает слияние, и таблица перестаёт работать.\n\nСветлоту пары намеренно не выравниваем. Первая версия выравнивала — и расхождение для дальтоника выросло вдесятеро: правка яркости двигает все три канала, в том числе рабочие. Как в оригинале, яркость маскирует шум: каждый кружок случайно светлее или темнее на ±21 %.\n\nУкладка кружков в два прохода: сначала внутрь самой цифры (кружок целиком внутри штриха), потом фон. В обратном порядке крупные фоновые кружки залезали на штрихи, и цифра читалась через раз — видно на скриншотах первой версии. Соседей ищем по сетке; около 1200 кружков на таблицу, построение 25–30 мс.\n\nСмена палитры — не обработка картинки: про каждый кружок известно, фигура это или фон, поэтому режим это просто другая функция цвета при отрисовке (как есть, усиление, daltonize, только светлота, симуляция, подсветка ответа).\n\nМиграция 0162: color_vision_results (всего, узнано, ошибки по типам), ручки GET|POST /tests/color-vision.\n\nПроверено в браузере: контраст пар (симуляция 0 против 80–165 для нормального зрения), читаемость цифр на скриншотах после двух правок укладки, все шесть палитр (серый даёт ровно нейтральный цвет, подсветка — чёрные кружки фигуры), полный прогон девяти таблиц с записью результата и разбором.'
);
-- +goose StatementEnd

